import heapq

def match(orders):
    trades = []

    # order_id -> dict with side, price, qty (remaining), arrival, active
    book = {}

    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)

    arrival_counter = 0

    def clean_buy_heap():
        while buy_heap:
            neg_price, arr, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, price, qty, is_market):
        # price is None if market (no price check), otherwise int
        # returns remaining qty after matching
        nonlocal trades
        if side == 'buy':
            while qty > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                top_price, top_arr, top_id = sell_heap[0]
                if not is_market:
                    if top_price > price:
                        break
                info = book[top_id]
                trade_qty = min(qty, info['qty'])
                trades.append([None, top_id, top_price, trade_qty])  # buy_id filled later
                info['qty'] -= trade_qty
                qty -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
                    clean_sell_heap()
        else:
            while qty > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, top_arr, top_id = buy_heap[0]
                top_price = -neg_price
                if not is_market:
                    if top_price < price:
                        break
                info = book[top_id]
                trade_qty = min(qty, info['qty'])
                trades.append([top_id, None, top_price, trade_qty])  # sell_id filled later
                info['qty'] -= trade_qty
                qty -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
                    clean_buy_heap()
        return qty

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            arrival_counter += 1
            arr = arrival_counter

            # match first
            trade_start_idx = len(trades)
            remaining = match_incoming(side, price, qty, is_market=False)

            # fill in the incoming id in trades recorded during this call
            for i in range(trade_start_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid

            if remaining > 0:
                info = {'side': side, 'price': price, 'qty': remaining, 'arrival': arr, 'active': True}
                book[oid] = info
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arr, oid))
                else:
                    heapq.heappush(sell_heap, (price, arr, oid))
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'arrival': arr, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            arrival_counter += 1
            arr = arrival_counter

            trade_start_idx = len(trades)
            remaining = match_incoming(side, price, qty, is_market=False)

            for i in range(trade_start_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid

            book[oid] = {'side': side, 'price': price, 'qty': 0, 'arrival': arr, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            arrival_counter += 1
            arr = arrival_counter

            trade_start_idx = len(trades)
            remaining = match_incoming(side, None, qty, is_market=True)

            for i in range(trade_start_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid

            book[oid] = {'side': side, 'price': None, 'qty': 0, 'arrival': arr, 'active': False}

    return trades

